def get_dict_type(dct, max_typed_dict_size):
    if not isinstance(dct, dict):
        return type(dct)
    if not dct:
        return Dict[str, Any]
    key_types = shrink_types([type(key) for key in dct.keys()], max_typed_dict_size)
    value_types = shrink_types([type(value) for value in dct.values()], max_typed_dict_size)
    return Dict[key_types, value_types]


def get_type(obj, max_typed_dict_size):
    if obj is None:
        return NoneType
    if obj is NotImplemented:
        return NotImplementedType
    if isinstance(obj, (int, str, float, bool, complex)):
        return type(obj)
    if isinstance(obj, (list, tuple, set, frozenset)):
        if not obj:
            return type(obj)[type(obj).__args__[0]]
        elem_types = shrink_types([type(item) for item in obj], max_typed_dict_size)
        return type(obj)[elem_types]
    if isinstance(obj, dict):
        return get_dict_type(obj, max_typed_dict_size)
    if isinstance(obj, types.FunctionType):
        return Callable
    if isinstance(obj, type):
        return Type[obj]
    if hasattr(obj, "__class__"):
        return obj.__class__
    return type(obj)
